  const phone = c.phones[0]; const text = (ST().templates.proof || '').replace('{name}', c.name).replace('{amount}', M(t.amount)).replace('{recipient}', t.recipient).replace('{ref}', t.ref || '—').replace('{due}', due > 0 ? M(due) : 'مدفوع ✅').replace('{office}', ST().name);
