async function reqFromProof(pid) { const p = S.proofs[pid], e = p.ext || {}, g = C.guessCustomer(S, e); if (e.dir === 'in') return quickForm({ kind: 'receive', amount: e.amount, senderPhone: g ? '' : e.sender, provider: e.provider, ref: e.ref, customerId: g ? g.id : null, proofId: pid, why: g ? g.why : 'اتسجلت من الإثبات', exec: true }); quickForm({ amount: e.amount, recipient: e.recipient, provider: e.provider, fee: e.fee, ref: e.ref, customerId: g ? g.id : null, proofId: pid, why: g ? g.why : 'اتسجلت من الصورة', exec: true }); }

