V.cust = id => { const c = cust(id); if (!c) return '<div class="card empty">العميل مش موجود</div>'; const L = LG(), l = L.parties[id] || { count: 0, amount: 0, commission: 0, paid: 0, balance: 0, open: [] };
  const rows = []; Object.values(S.tx).filter(t => t.customerId === id).forEach(t => rows.push({ t: t.executedAt || t.createdAt, kind: 'tx', o: t })); Object.values(S.colls).filter(k => k.partyId === id).forEach(k => rows.push({ t: k.date || k.createdAt, kind: 'coll', o: k }));
  Object.values(S.adjusts).filter(a => a.partyId === id).forEach(a => rows.push({ t: a.date || a.createdAt, kind: 'adj', o: a })); Object.values(S.payouts).filter(p => p.partyId === id).forEach(p => rows.push({ t: p.date || p.createdAt, kind: 'pay', o: p }));
  rows.sort((a, b) => a.t < b.t ? -1 : 1); let run = c.opening || 0;
  const body = rows.map(r => { if (r.kind === 'adj') { const a = r.o; if (!a.reversed) run += a.delta; return `<tr ${a.reversed ? 'style="opacity:.5"' : ''}><td>${T(r.t)}</td><td>تسوية</td><td>${H(a.reason || '')}</td><td>${a.delta > 0 ? M(a.delta) : ''}</td><td>${a.delta < 0 ? M(-a.delta) : ''}</td><td><b>${M(run)}</b></td></tr>`; }
    if (r.kind === 'pay') { const p = r.o; if (!p.reversed) run += p.amount; return `<tr><td>${T(r.t)}</td><td>صرفنا له</td><td>${p.method === 'wallet' ? 'من ' + H(wName(p.walletId)) : 'كاش'} ${H(p.note || '')}</td><td>${M(p.amount)}</td><td></td><td><b>${M(run)}</b></td></tr>`; }
    if (r.kind === 'tx' && r.o.kind === 'receive') { const t = r.o, eff = C.isEffective(t), cr = eff ? t.amount - (t.commission || 0) : 0; run -= cr; return `<tr><td>${T(r.t)}</td><td>${H(t.no)} سحب كاش ${stTag(t.status)}</td><td>حوّل لنا ${M(t.amount)} − عمولة ${M(t.commission || 0)}</td><td></td><td>${eff ? M(cr) : '—'}</td><td><b>${M(run)}</b></td></tr>`; }
    if (r.kind === 'tx') { const t = r.o, eff = C.isEffective(t), due = eff ? t.amount + (t.commission || 0) : 0; run += due; return `<tr><td>${T(r.t)}</td><td>${H(t.no)} ${stTag(t.status)}</td><td>تحويل ${M(t.amount)} → <span dir="ltr">${H(t.recipient)}</span>${t.commission ? ' + عمولة ' + M(t.commission) : ''}</td><td>${eff ? M(due) : '—'}</td><td></td><td><b>${M(run)}</b></td></tr>`; }
    const k = r.o; if (!k.reversed) run -= k.amount; return `<tr ${k.reversed ? 'style="opacity:.5"' : ''}><td>${T(r.t)}</td><td>تحصيل ${k.reversed ? '<span class="tag r">ملغي</span>' : ''}</td><td>${k.method === 'wallet' ? 'على ' + H(wName(k.walletId)) : 'كاش'}${k.note ? ' · ' + H(k.note) : ''}</td><td></td><td>${M(k.amount)}</td><td><b>${M(run)}</b></td></tr>`; }).reverse().join('') + (c.opening ? `<tr><td>${T(c.createdAt)}</td><td>رصيد افتتاحي</td><td>${c.opening > 0 ? 'عليه' : 'ليه'}</td><td>${c.opening > 0 ? M(c.opening) : ''}</td><td>${c.opening < 0 ? M(-c.opening) : ''}</td><td><b>${M(c.opening)}</b></td></tr>` : '');
  const stmt = `كشف حساب ${c.name} — ${ST().name}\nعدد العمليات: ${l.count}\nإجمالي المحوّل: ${M(l.amount)}\nالعمولات: ${M(l.commission)}\nاتدفع: ${M(l.paid)}\nالمتبقي: ${M(l.balance)}`;
  return `<h1>${ic('user')} ${H(c.name)} <span class="tag">${H(c.type)}</span>${c.status !== 'active' ? `<span class="tag w">${c.status === 'review' ? 'يحتاج مراجعة' : 'موقوف'}</span>` : ''}<span class="sp"></span><button class="s" onclick="A.custForm('${id}')">${ic('edit')}تعديل</button><button class="w" onclick="A.collect('${id}')">${ic('cash')}تحصيل / إيداع</button><button onclick="A.newReq('${id}')">${ic('bolt')}تحويل</button><button class="s" onclick="A.quick({kind:'receive',customerId:'${id}'})">${ic('down')}سحب كاش</button><button class="s" onclick="A.payOut('${id}')">${ic('up')}صرف له</button><button class="g" onclick="A.partyAdjust('${id}')">${ic('edit')}تسوية</button></h1>
  <div class="grid">${kpi('ops', 'العمليات', N(l.count))}${kpi('wallet', 'إجمالي المحوّل', M(l.amount), 'var(--sky)')}${kpi('bolt', 'العمولات', M(l.commission))}${kpi('cash', 'اتحصل', M(l.paid))}${kpi('alert', l.balance >= 0 ? 'عليه' : 'له عندنا', M(Math.abs(l.balance)), l.balance > 0 ? 'var(--bad)' : 'var(--ok)', '', c.credit ? 'الحد ' + M(c.credit) : '')}</div>
  <div class="card"><div class="kv"><span>الأرقام</span><b dir="ltr">${H(c.phones.join(' · '))}</b><span>أول تعامل</span><b>${T(c.createdAt)}</b><span>طريقة التحصيل</span><b>${H({ prepaid: 'مقدم', after: 'بعد التنفيذ', eod: 'آخر اليوم', broker: 'وسيط' }[c.terms] || '')}</b>${c.notes ? `<span>ملاحظات</span><b>${H(c.notes)}</b>` : ''}</div><div class="row" style="margin-top:10px"><a class="btn b" target="_blank" href="${waLink(c.phones[0], stmt)}">${ic('wa')}ابعتله كشف الحساب</a><button class="g" onclick="window.print()">${ic('print')}طباعة</button></div></div>
  <div class="card sc"><b>كشف الحساب</b><table style="margin-top:8px"><tr><th>الوقت</th><th>البند</th><th>التفاصيل</th><th>عليه</th><th>دفع</th><th>الرصيد</th></tr>${body || '<tr><td colspan="6" class="empty">مفيش حركات</td></tr>'}</table></div>`; };

/* =================== التحصيل =================== */
function collect(partyId, txId) { if (!need('collect')) return; const L = LG(), parties = Object.values(S.customers); const sel = partyId || '';
  const openOf = pid => (L.parties[pid] || { open: [] }).open; const ws = Object.values(S.wallets).filter(w => w.status !== 'archived');
  modal(`<h3>${ic('cash')} تسجيل تحصيل</h3><div class="fg"><div class="full"><label>من مين</label><select id="koP">${parties.map(c => `<option value="${c.id}" ${c.id === sel ? 'selected' : ''}>${H(c.name)} — عليه ${M((L.parties[c.id] || {}).balance || 0)}</option>`).join('')}</select></div>
  <div><label>المبلغ</label><input id="koA" inputmode="decimal"></div><div><label>طريقة الدفع</label><select id="koM"><option value="cash">كاش في الخزنة</option>${ws.map(w => `<option value="w:${w.id}">تحويل على ${H(w.name)}</option>`).join('')}</select></div>
  <div><label>التاريخ والوقت</label><input id="koD" type="datetime-local" value="${new Date(Date.now() - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 16)}"></div><div><label>ملاحظات</label><input id="koN"></div></div>
  <label>توزيع المبلغ</label><div id="koO"></div><div class="row" style="margin-top:12px"><button id="koGo">${ic('check')}تسجيل التحصيل</button><button class="g" onclick="A.closeM()">رجوع</button></div>`);
  const drawOpen = () => { const o = openOf(val('koP')); $('#koO').innerHTML = o.length ? `<div class="muted" style="font-size:13px">من غير اختيار: بيتخصم من الأقدم للأحدث. أو حدد عمليات بعينها:</div>${o.map(x => { const t = S.tx[x.txId]; return `<label style="display:flex;gap:8px;align-items:center;font-weight:600;color:var(--ink)"><input type="checkbox" class="koX" value="${x.txId}" data-rest="${x.rest}" style="width:auto;min-height:0" ${x.txId === txId ? 'checked' : ''}> ${H(t.no)} · ${M(t.amount)} → <span dir="ltr">${H(t.recipient)}</span> · باقي ${M(x.rest)}</label>`; }).join('')}` : '<div class="muted">مفيش عمليات مفتوحة — هيتسجل رصيد له عندنا</div>';
    const sum = () => { const s = $$('.koX:checked').reduce((a, b) => a + (+b.dataset.rest), 0); if (s) $('#koA').value = C.fromP(s); }; $$('.koX').forEach(x => x.onchange = sum); if (txId) sum(); else { const b = (L.parties[val('koP')] || {}).balance || 0; if (b > 0) $('#koA').placeholder = 'المتبقي ' + C.fromP(b); } };
  $('#koP').onchange = drawOpen; drawOpen();
  $('#koGo').onclick = async () => { const amount = C.toP(val('koA')); if (amount <= 0) return toast('اكتب المبلغ', 'r'); const m = val('koM'); let left = amount; const alloc = $$('.koX:checked').map(x => { const a = Math.min(+x.dataset.rest, left); left -= a; return { txId: x.value, amount: a }; }).filter(a => a.amount > 0);
    await dispatch('coll.add', { id: C.uid(), partyId: val('koP'), amount, method: m === 'cash' ? 'cash' : 'wallet', walletId: m.startsWith('w:') ? m.slice(2) : null, date: new Date(val('koD')).toISOString(), alloc, note: val('koN') }); closeM(); toast('اتسجل التحصيل', 'g'); }; }
V.collect = () => { const L = LG(), d = todayDay(), H2 = ST().dayStartHour; const rows = Object.values(S.customers).map(c => { const l = L.parties[c.id] || { balance: 0, open: [] }; const tt = Object.values(S.tx).filter(t => t.customerId === c.id && C.isEffective(t) && C.dayOf(t.executedAt, H2) === d); const kk = Object.values(S.colls).filter(k => k.partyId === c.id && !k.reversed && C.dayOf(k.date || k.createdAt, H2) === d);
    return { c, l, tAmt: tt.reduce((a, t) => a + t.amount, 0), tCom: tt.reduce((a, t) => a + (t.commission || 0), 0), kSum: kk.reduce((a, k) => a + k.amount, 0), cnt: tt.length }; }).filter(r => r.cnt || r.kSum || r.l.balance).sort((a, b) => b.l.balance - a.l.balance);
  const recent = Object.values(S.colls).sort((a, b) => (b.date || b.createdAt) > (a.date || a.createdAt) ? 1 : -1).slice(0, 25);
  return `<h1>${ic('cash')} تحصيلات اليوم <span class="sp"></span><button onclick="A.collect()">${ic('plus')}تسجيل تحصيل</button><button class="b" onclick="A.qa('remind')">${ic('msg')}تذكير المتأخرين</button></h1>
  <div class="card sc"><table><tr><th>العميل / الوسيط</th><th>عمليات النهارده</th><th>عمولات</th><th>اتحصل النهارده</th><th>الرصيد المتبقي</th><th>الحالة</th><th></th></tr>${rows.map(r => `<tr><td><a href="#cust/${r.c.id}"><b>${H(r.c.name)}</b></a> <small class="muted">${H(r.c.type)}</small></td><td>${M(r.tAmt)} <small class="muted">(${N(r.cnt)})</small></td><td>${M(r.tCom)}</td><td>${M(r.kSum)}</td><td><b class="${r.l.balance > 0 ? 'neg' : 'pos'}">${M(r.l.balance)}</b></td><td>${r.l.balance <= 0 ? '<span class="tag">مسدد</span>' : r.l.paid ? '<span class="tag w">جزئي</span>' : '<span class="tag r">مفتوح</span>'}</td><td>${r.l.balance > 0 ? `<button class="w" onclick="A.collect('${r.c.id}')">${ic('cash')}تحصيل</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">مفيش حسابات مفتوحة</td></tr>'}</table></div>
  <div class="card sc"><b>آخر التحصيلات</b><table style="margin-top:8px"><tr><th>الوقت</th><th>من</th><th>المبلغ</th><th>الطريقة</th><th>ملاحظة</th><th></th></tr>${recent.map(k => `<tr ${k.reversed ? 'style="opacity:.5"' : ''}><td>${T(k.date || k.createdAt)}</td><td>${H((cust(k.partyId) || {}).name || '—')}</td><td>${M(k.amount)}</td><td>${k.method === 'wallet' ? H(wName(k.walletId)) : 'كاش'}</td><td>${H(k.note || '')}${k.reversed ? ' <span class="tag r">ملغي: ' + H(k.reverseReason) + '</span>' : ''}</td><td>${!k.reversed ? `<button class="g" onclick="A.revColl('${k.id}')">${ic('undo')}عكس</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">لسه مفيش</td></tr>'}</table></div>`; };
function revColl(id) { if (!need('balances')) return; prompt2('عكس التحصيل (بحركة عكسية — مش مسح)', 'السبب', async r => { await dispatch('coll.reverse', { id, reason: r }); toast('اتعكس', 'g'); }, { area: true }); }

/* =================== المحافظ والخزنة =================== */
V.wallets = () => { const B = BL(), W = Object.values(S.wallets).filter(w => w.status !== 'archived' && w.provider !== 'instapay'), mv = Object.values(S.moves).sort((a, b) => (b.date || b.createdAt) > (a.date || a.createdAt) ? 1 : -1).slice(0, 30), ex = Object.values(S.exps).sort((a, b) => (b.date || b.createdAt) > (a.date || a.createdAt) ? 1 : -1).slice(0, 20);
  const K = { topup: 'شحن محفظة من الخزنة', withdraw: 'سحب من محفظة للخزنة', transfer: 'تحويل بين محافظ', deposit: 'إيداع في الخزنة', drawing: 'سحب صاحب المكتب', adjust: 'تسوية' };
  return `<h1>${ic('wallet')} المحافظ والخزنة <span class="sp"></span><button onclick="A.walletForm()">${ic('plus')}محفظة / حساب</button></h1>
  <div class="grid">${kpi('cash', 'الخزنة (كاش)', M(B.cash))}${kpi('wallet', 'إجمالي المحافظ', M(B.walletsTotal), 'var(--sky)')}${kpi('shield', 'إجمالي السيولة', M(B.liquidity), '#7c5cc4', '', 'للعرض بس — الكاش والمحافظ مش رصيد واحد')}</div>
  <div class="card"><div class="row"><b class="f">الخزنة النقدية</b><button class="s" onclick="A.moveForm('deposit')">${ic('down')}إيداع</button><button class="s" onclick="A.moveForm('drawing')">${ic('up')}سحب</button><button class="w" onclick="A.expForm()">${ic('tag')}مصروف</button><button class="g" onclick="A.moveForm('adjust','cash')">${ic('edit')}تسوية</button></div></div>
  ${W.map(w => { const b = B.wallets[w.id], lim = w.minAlert != null && w.minAlert !== '' ? w.minAlert : (ST().alerts || {}).walletLow; return `<div class="tx" style="--c:${lim && b < lim ? 'var(--bad)' : 'var(--sky)'}"><div class="h"><b style="font-size:17px">${H(w.name)}</b><span class="tag b">${H(provName(w.provider))}</span>${w.status === 'stopped' ? '<span class="tag r">موقوفة</span>' : ''}<span style="flex:1"></span><span class="amt ${b < 0 ? 'neg' : ''}">${M(b)}</span></div><div class="meta">${H(w.holder || '')} · <span dir="ltr">${H(w.number || '')}</span> · افتتاحي ${M(w.opening)} · رسوم: ${feeTxt(w.fee)}${lim ? ' · تنبيه تحت ' + M(lim) : ''}${w.limits ? ' · ' + H(w.limits) : ''}</div>${(() => { const u = C.walletUsage(S, w.id, todayDay(), ST().dayStartHour), bar = (l, used, lim) => { const p = Math.min(100, used / lim * 100); return `<div style="flex:1;min-width:140px"><small class="muted">${l}: ${M(used)} من ${M(lim)}</small><div class="prog"><i style="width:${p}%;background:${p > 90 ? 'var(--bad)' : p > 70 ? 'var(--warn)' : 'var(--pri)'}"></i></div></div>`; }; return (w.dailyLimit || w.monthlyLimit) ? `<div class="row" style="margin-top:8px">${w.dailyLimit ? bar('اليوم', u.day, w.dailyLimit) : ''}${w.monthlyLimit ? bar('الشهر', u.month, w.monthlyLimit) : ''}</div>` : ''; })()}
  <div class="acts"><button class="s" onclick="A.moveForm('topup',null,'${w.id}')">${ic('down')}شحن من الخزنة</button><button class="s" onclick="A.moveForm('withdraw','${w.id}')">${ic('up')}سحب للخزنة</button><button class="s" onclick="A.moveForm('transfer','${w.id}')">${ic('ops')}تحويل لمحفظة</button><button class="g" onclick="A.moveForm('adjust','${w.id}')">${ic('edit')}تسوية</button><button class="g" onclick="A.walletLedger('${w.id}')">${ic('ledger')}الحركات</button><button class="g" onclick="A.walletForm('${w.id}')">${ic('set')}إعدادات</button></div></div>`; }).join('') || '<div class="card empty">ضيف محافظك: فودافون كاش، اتصالات كاش، انستاباي… ومحفظتين من نفس النوع عادي</div>'}
  <div class="card sc"><b>حركات الخزنة والمحافظ</b><table style="margin-top:8px"><tr><th>الوقت</th><th>النوع</th><th>التفاصيل</th><th>المبلغ</th><th>السبب</th><th></th></tr>${mv.map(m => `<tr ${m.reversed ? 'style="opacity:.5"' : ''}><td>${T(m.date || m.createdAt)}</td><td>${K[m.kind]}</td><td>${m.from ? H(wName(m.from)) : m.kind === 'adjust' ? (m.account === 'cash' ? 'الخزنة' : H(wName(m.account))) : 'الخزنة'} ${m.to ? '→ ' + H(wName(m.to)) : ''}</td><td>${M(m.kind === 'adjust' ? m.delta : m.amount)}${m.fee ? ' + رسوم ' + M(m.fee) : ''}</td><td>${H(m.note || m.reason || '')}</td><td>${!m.reversed ? `<button class="g" onclick="A.revMove('${m.id}')">${ic('undo')}</button>` : '<span class="tag r">معكوسة</span>'}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">مفيش</td></tr>'}</table></div>
  <div class="card sc"><b>المصروفات</b><table style="margin-top:8px"><tr><th>الوقت</th><th>البند</th><th>المبلغ</th><th>من</th><th></th></tr>${ex.map(e => `<tr ${e.reversed ? 'style="opacity:.5"' : ''}><td>${T(e.date || e.createdAt)}</td><td>${H(e.category)} ${H(e.note || '')}</td><td>${M(e.amount)}</td><td>${e.walletId ? H(wName(e.walletId)) : 'الخزنة'}</td><td>${!e.reversed ? `<button class="g" onclick="A.revExp('${e.id}')">${ic('undo')}</button>` : '<span class="tag r">معكوس</span>'}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">مفيش</td></tr>'}</table></div>`; };
const feeTxt = f => !f || !f.value && f.mode !== 'tiers' ? 'من غير' : f.mode === 'percent' ? N(f.value) + '٪' + (f.min ? ' (أقل ' + M(f.min) + ')' : '') + (f.max ? ' (أقصى ' + M(f.max) + ')' : '') : f.mode === 'fixed' ? M(f.value) : 'شرائح';
function walletForm(id, then) { if (id && S.wallets[id] && S.wallets[id].provider === 'instapay') return instaForm(id); const w = id ? S.wallets[id] : { provider: 'vodafone', opening: 0, status: 'active', fee: { mode: 'fixed', value: 0 } }; const f = w.fee || { mode: 'fixed', value: 0 };
  modal(`<h3>${ic('wallet')} ${id ? 'إعدادات ' + H(w.name) : 'محفظة / حساب جديد'}</h3><div class="fg"><div><label>الخدمة</label><select id="wfP">${ST().providers.map(p => `<option value="${p.key}" ${w.provider === p.key ? 'selected' : ''}>${H(p.name)}</option>`).join('')}</select></div><div><label>اسم تمييزي</label><input id="wfN" value="${H(w.name || '')}" placeholder="مثلاً: فودافون ١ — خط المحل"></div>
  <div><label>اسم صاحب الحساب</label><input id="wfH" value="${H(w.holder || '')}"></div><div><label>رقم الشريحة / الحساب</label><input id="wfR" dir="ltr" value="${H(w.number || '')}"></div><div><label>الفرع</label><select id="wfBr"><option value="">كل الفروع (مشتركة)</option>${allBranches().map(b => `<option value="${b.id}" ${(w.branch || (!id && BR !== 'all' ? BR : '')) === b.id ? 'selected' : ''}>${H(b.name)}</option>`).join('')}</select></div><div><label>المسؤول عنها</label><input id="wfU" value="${H(w.keeper || '')}"></div>
  <div><label>الرصيد الافتتاحي</label><input id="wfO" inputmode="decimal" value="${C.fromP(w.opening)}" ${id && !can('balances') ? 'disabled' : ''}></div><div><label>نبّهني لو الرصيد قل عن</label><input id="wfL" inputmode="decimal" value="${w.minAlert ? C.fromP(w.minAlert) : ''}"></div>
  <div><label>رسوم الخدمة على التحويل</label><select id="wfFM"><option value="fixed" ${f.mode === 'fixed' ? 'selected' : ''}>مبلغ ثابت</option><option value="percent" ${f.mode === 'percent' ? 'selected' : ''}>نسبة ٪</option></select></div><div><label>القيمة</label><input id="wfFV" inputmode="decimal" value="${f.mode === 'percent' ? (f.value || 0) : C.fromP(f.value || 0)}"></div>
  <div><label>أقل رسوم</label><input id="wfFn" inputmode="decimal" value="${f.min ? C.fromP(f.min) : ''}"></div><div><label>أقصى رسوم</label><input id="wfFx" inputmode="decimal" value="${f.max ? C.fromP(f.max) : ''}"></div>
  <div><label>الحد اليومي للتحويل</label><input id="wfDL" inputmode="decimal" value="${w.dailyLimit ? C.fromP(w.dailyLimit) : ''}" placeholder="مثلاً 60000"></div><div><label>الحد الشهري</label><input id="wfML" inputmode="decimal" value="${w.monthlyLimit ? C.fromP(w.monthlyLimit) : ''}" placeholder="مثلاً 200000"></div><div class="full"><label>ملاحظات القيود</label><input id="wfX" value="${H(w.limits || '')}"></div><div><label>الحالة</label><select id="wfS"><option value="active" ${w.status === 'active' ? 'selected' : ''}>شغالة</option><option value="stopped" ${w.status === 'stopped' ? 'selected' : ''}>موقوفة</option><option value="archived">أرشيف (تختفي)</option></select></div></div>
  <div class="row" style="margin-top:12px"><button id="wfGo">${ic('check')}حفظ</button><button class="g" onclick="A.closeM()">رجوع</button></div>`);
  $('#wfGo').onclick = async () => { const name = val('wfN').trim() || provName(val('wfP')); const fm = val('wfFM'), fv = fm === 'percent' ? parseFloat(C.normDigits(val('wfFV'))) || 0 : C.toP(val('wfFV'));
    const d = { id: id || C.uid(), provider: val('wfP'), name, holder: val('wfH'), number: val('wfR'), minAlert: val('wfL') ? C.toP(val('wfL')) : null, fee: { mode: fm, value: fv, min: val('wfFn') ? C.toP(val('wfFn')) : null, max: val('wfFx') ? C.toP(val('wfFx')) : null }, limits: val('wfX'), branch: val('wfBr'), keeper: val('wfU'), dailyLimit: val('wfDL') ? C.toP(val('wfDL')) : null, monthlyLimit: val('wfML') ? C.toP(val('wfML')) : null, status: val('wfS') };
    if (!id || can('balances')) d.opening = C.toP(val('wfO')); await dispatch('wallet.upsert', d); closeM(); toast('اتحفظ', 'g'); if (then) setTimeout(then, 60); }; }
