  <div class="grid">${kpi('ops', 'عدد', N(R.length))}${kpi('wallet', 'المبالغ', M(C.toP(tot.amount)), 'var(--sky)')}${kpi('bolt', 'العمولات', M(C.toP(tot.com)))}${kpi('tag', 'الرسوم', M(C.toP(tot.fee)), 'var(--warn)')}</div>
