function closeText(d, c) { const s = c.summary || {}; return `تقرير إقفال ${ST().name} — ${d}\nاتبعت: ${M(s.amount || 0)} (${N((s.executed || 0) - (s.recvCount || 0))} تحويل)\nوصل: ${M((s.collected || 0) + (s.recvAmount || 0))}\nالعمولات: ${M(s.commission || 0)}\nرسوم ونسب: ${M((s.fees || 0) + (s.supFees || 0))}\nصافي الربح: ${M(s.profit || 0)}\nالخزنة: محسوبة ${M(c.expected)} · فعلية ${M(c.counted)}${c.diff ? ' · فرق ' + M(c.diff) + ' (' + (c.reason || '') + ')' : ' · مظبوطة'}\n` + Object.values(S.wallets).filter(w => c.walletBal && c.walletBal[w.id] != null).map(w => `${w.name}: ${M(c.walletBal[w.id])}`).join('\n') + (c.notes ? '\nملاحظات: ' + c.notes : '') + `\nاتقفل بواسطة ${c.by || ''} — ${T(c.closedAt)}`; }
