  <div class="grid">${kpi('up', 'عليا للموردين', M(owe), 'var(--bad)')}${kpi('down', 'ليا عند الموردين', M(they), 'var(--ok)')}${kpi('ops', 'اتبعت عن طريقهم النهارده', M(list.reduce((a, s) => a + ((bs['s:' + s.id] || {}).out || 0), 0)), 'var(--sky)')}${kpi('tag', 'نسبهم النهارده', M(list.reduce((a, s) => a + ((bs['s:' + s.id] || {}).supFees || 0), 0)), 'var(--warn)')}</div>
