const allBranches = () => ((ME && ME.all_branches) || []).filter(b => b.active !== false);
const myBranches = () => { const A = allBranches(); if (!ME || ME.role === 'admin' || !(ME.branches || []).length) return A; return A.filter(b => ME.branches.includes(b.id)); };
const brName = id => (((ME && ME.all_branches) || []).find(b => b.id === id) || {}).name || '';
