SV.sms = () => `<div class="card"><b>${ic('msg')} رسايل الـSMS توصل لوحدها</b><p class="muted" style="line-height:1.9">أول ما رسالة تحويل أو استلام توصل على خط المحفظة، الموبايل بيبعتها لـ${BRAND} أوتوماتيك، فتظهر في «الإثباتات» متقرية: المبلغ والرقم والمرجع، ومتربطة بالعميل من رقمه. <b>مفيش أي خصم أو إضافة من غير تأكيدك.</b></p>
  ${can('users') ? `<div id="smsBox"><button onclick="A.smsKey()">${ic('lock')}اعرض بيانات الربط</button></div>` : '<div class="alert">بيانات الربط بتظهر لمدير المكتب بس</div>'}</div>
  <div class="card"><b>أندرويد — تطبيق MacroDroid (مجاني)</b><ol class="cs-steps"><li>نزّل <b>MacroDroid</b> من جوجل بلاي وافتحه على الموبايل اللي فيه خط المحفظة.</li><li>«Add Macro» (ماكرو جديد) ← المُشغّل <b>SMS Received</b> (يعني «وصلت رسالة») ← اختار المرسل (زي VF-Cash) أو «Any» (أي حد) مع كلمة «جنيه».</li><li>الإجراء <b>HTTP Request</b> (طلب إنترنت) ← Method: <b>POST</b> ← حط «اللينك» من فوق.</li><li>في Headers (العناوين) ضيف: الاسم <b>apikey</b> والقيمة من فوق.</li><li>في Body (نص الطلب) اختار <b>JSON</b> والصق «نص الطلب» من فوق، وبدّل كلمة SMS_TEXT بـ<b>[sms_message]</b> وكلمة SMS_FROM بـ<b>[sms_number]</b> من زرار «...» (Magic Text).</li><li>احفظ، وجرّب بتحويل صغير — لازم الرسالة تظهر هنا في «الإثباتات» خلال ثواني.</li></ol><p class="muted" style="font-size:13px">لو وقفت معاك في أي خطوة ابعت سكرين للدعم ونظبطهالك.</p></div>
  <div class="card"><b>آيفون — تطبيق الاختصارات (Shortcuts)</b><ol class="cs-steps"><li>الاختصارات ← «الأتمتة» ← أتمتة جديدة ← <b>الرسالة</b> ← «الرسالة تحتوي على»: جنيه ← اختار «تشغيل فوراً».</li><li>ضيف إجراء <b>الحصول على محتويات عنوان URL</b> وحط «اللينك».</li><li>الطريقة POST ← العناوين: <b>apikey</b> بالقيمة من فوق ← نص الطلب JSON بـ٣ حقول: <b>p_token</b> = المفتاح السري، <b>p_text</b> = «الرسالة»، <b>p_from</b> = «المُرسل».</li><li>احفظ وجرّب بتحويل صغير.</li></ol><p class="muted" style="font-size:13px">الأتمتة اللي بتشتغل لوحدها من غير ما تدوس محتاجة iOS 17 أو أحدث.</p></div>
  ${can('users') ? `<div class="card"><b>جرّب من هنا</b><p class="muted" style="font-size:13px">الصق رسالة حقيقية من المحفظة وابعتها بنفس الطريقة اللي الموبايل هيبعت بيها.</p><textarea id="smsT" placeholder="مثلاً: تم تحويل 5.00 جنيه لرقم 01007007277 مصاريف الخدمة 1 جنيه"></textarea><div class="row" style="margin-top:8px"><button class="s" onclick="A.smsTest()">${ic('msg')}ابعتها تجربة</button></div></div>` : ''}`;
async function smsKey(reset) { if (!need('users')) return; if (reset && !confirm('هيتعمل مفتاح جديد والقديم هيبطل — هتحتاج تحدّثه في تطبيق الأتمتة. تكمل؟')) return;
  const r = await sb.rpc('ph_sms_key', { p_reset: !!reset }); if (r.error) return toast(r.error.message, 'r'); SMSK = r.data;
  const url = SB_URL + '/rest/v1/rpc/ph_sms_in', body = JSON.stringify({ p_token: SMSK, p_text: 'SMS_TEXT', p_from: 'SMS_FROM' });
  $('#smsBox').innerHTML = [['اللينك (URL)', url], ['apikey', SB_KEY], ['المفتاح السري بتاع مكتبك (p_token)', SMSK], ['نص الطلب (Body — JSON)', body]].map(([l, v]) => `<label>${l}</label><div class="row"><input readonly dir="ltr" value="${H(v)}" style="flex:1;font-size:12px"><button class="s" onclick="A.copy(this.previousElementSibling.value)">${ic('copy')}نسخ</button></div>`).join('')
    + `<p class="muted" style="font-size:13px;line-height:1.8">المفتاح السري زي كلمة السر: اللي معاه يقدر يبعت رسايل لمكتبك بس (مايقدرش يشوف بياناتك). لو اتسرّب اعمل مفتاح جديد.</p><button class="g" onclick="A.smsKey(true)">مفتاح جديد</button>`; }
async function smsTest() { const t = val('smsT').trim(); if (t.length < 5) return toast('الصق رسالة الأول', 'r');
  if (!SMSK) { const r = await sb.rpc('ph_sms_key', { p_reset: false }); if (r.error) return toast(r.error.message, 'r'); SMSK = r.data; }
  const res = await fetch(SB_URL + '/rest/v1/rpc/ph_sms_in', { method: 'POST', headers: { apikey: SB_KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ p_token: SMSK, p_text: t, p_from: 'تجربة' }) }); const j = await res.json().catch(() => null);
  if (!res.ok) return toast('السيرفر رفض: ' + ((j && j.message) || res.status), 'r'); toast(j === 'dup' ? 'نفس الرسالة اتبعتت من شوية' : 'وصلت ✓ هتلاقيها في «الإثباتات»', 'g'); await syncNow(); }
async function pullSms() { if (!ME || !ME.org) return; const m = await dbGet('meta', 'smscur'); let cur = (m && m.org === ME.org) ? m.v : 0, got = 0;
  const r = await sb.from('ph_sms').select('id,sender,body,created_at').eq('org', ME.org).gt('id', cur).order('id').limit(200);
  if (r.error) { if (/ph_sms|PGRST205|schema cache|does not exist/i.test(r.error.message + r.error.code)) return; throw r.error; }
  for (const x of r.data) { cur = x.id; const id = 'sms-' + x.id; if (S.proofs[id]) continue; const ext = C.extractProof(x.body, ST().providers);
    await dispatch('proof.add', { id, hash: id, name: 'SMS ' + (x.sender || ''), size: 0, status: 'ready', source: 'sms', sender: x.sender, smsAt: x.created_at, ocrText: x.body, ext, forTx: null });
    const mt = C.matchProof(S, ext, x.created_at); await dispatch('proof.update', { id, cands: mt.candidates, suggested: mt.suggested, ambiguous: mt.ambiguous }); got++; }
  await dbPut('meta', { k: 'smscur', v: cur, org: ME.org }); if (got && !LOCKED) toast(got === 1 ? 'وصلت رسالة SMS جديدة — في «الإثباتات»' : 'وصلت ' + N(got) + ' رسايل SMS جديدة', 'g'); }

